(*
  GET FLOW FROM PRESSURE FUNCTION
  Physics-based flow calculation: Q = sqrt(Ps / (α + β))
  Author: AhmadMohammad | Date: 2025-11-05
  Predicts flow from pressure sensor reading
  Inputs: fluid type, nozzle type, gauge pressure (bar)
  Output: flow rate (L/min)
  Fluid: 0=Water, 1=ISOXEL_5450, 2=DFAB_3D
  Nozzle: 0=TX-0.60, 1=TX-2.5, 2=TX-4, 3=TX-8, 4=Hose6mm, 5=Hose18mm
*)

rBeta := GetBeta(iFluid, iNozzle);
rAlpha := GetAlpha(iFluid);
rDenom := rAlpha + rBeta;

IF rDenom > 0.0001 AND rPs >= 0.0 THEN
  rFlow := SQRT(rPs / rDenom);
ELSE
  rFlow := 0.0;
END_IF;

GetFlowFromPressure := rFlow;
